package fixture

import "testing"

func TestCountVowels(t *testing.T) {
	cases := map[string]int{"Hello World": 3, "AEIOU": 5, "xyz": 0}
	for s, want := range cases {
		if got := CountVowels(s); got != want {
			t.Fatalf("CountVowels(%q) = %d, want %d", s, got, want)
		}
	}
}
